mapper.select:
SELECT  FROM t_agreement_capability
WHERE agreement_id IN #{id}
ORDER BY agreement_capability_id

mapper.update:
UPDATE t_agreement_capability SET status = #{status}, execution_status = #{executionStatus}, update_time = #{now}
WHERE agreement_capability_id = #{capability.agreementCapabilityId} AND status = #{capability.status}
    AND execution_status <=> #{capability.executionStatus}

UPDATE t_agreement_capability SET execution_status = #{executionStatus}, update_time = #{now}
WHERE agreement_capability_id = #{capability.agreementCapabilityId} AND status = 'ACTIVE'
    AND execution_status = #{capability.executionStatus}

mapper.select:
SELECT DISTINCT agreement_id FROM t_agreement_capability
WHERE execution_status IN #{status}
    AND agreement_id > #{afterAgreementId} AND MOD(agreement_id, #{shardTotal}) = #{shardIndex}
ORDER BY agreement_id LIMIT #{limit}

mapper.update:
UPDATE t_agreement_capability
SET effective_from = #{effectiveFrom}, effective_to = #{effectiveTo}, rolling_reserve_rate = #{rollingReserveRate},
    rolling_reserve_days = #{rollingReserveDays}, require_3ds = #{require3ds}, update_time = #{now}
WHERE agreement_capability_id = #{capability.agreementCapabilityId} AND update_time = #{capability.updateTime}
